@startuml

enum LevelOfTutoring {
  PrimarySchool
  HighSchool
  University
}

enum PaymentKind {
  CreditCard
  WireTransfer
}

class User {
  + name : string
  + email : string
}

class Tutor extends User {
  + bankAccount : string
}

class Student extends User {}

class TutoringOffer {
  + subject : string
  + levelOfExpertise : LevelOfTutoring
  + hourlyPrice : float
}

class TutorAvailability {
  + dayOfWeek : string
  + startTime : time
  + endTime : time
}

class TutoringRequest {
  + level : LevelOfTutoring
  + suggestedDate : date
  + suggestedTime : time
}

class TutoringSession {
  + sessionDate : date
  + sessionTime : time
  + price : float
}

Tutor "1" -- "*" TutoringOffer : offers
Tutor "1" -- "*" TutorAvailability : specifies
Tutor "1" -- "*" TutoringRequest : receives
Student "1" -- "*" TutoringRequest : makes
Student "1" -- "*" TutoringSession : attends
Tutor "1" -- "*" TutoringSession : conducts
TutoringRequest "1" -- "0..1" TutoringSession : becomes

@enduml

